-- North Carolina, all 170 in one file. The state had eight stops.
--
-- Three dropped as duplicates, and the third is the interesting one.
--
-- The Cryptozoology & Paranormal Museum and World's Largest Chest of Drawers
-- were both already here under slugs differing only by a leading "the" and by
-- how an apostrophe was handled. Neither showed up in the slug check.
--
-- World's Largest Duncan Phyfe Chair is at zero metres from a stop already in
-- the index called The Big Chair. Same object in Thomasville, entirely
-- different name — nothing but a coordinate comparison would ever have caught
-- it, which is the clearest case yet for running both checks rather than
-- trusting slugs.
--
-- Mystery Hill goes in as mystery-hill-blowing-rock, because Onsted, Michigan
-- holds the plain slug. Two different tilted rooms.
--
-- Twenty-two access words arrived, more than any state so far — ticketed,
-- tour-only, permission-required, cemetery-hours, boat-access, event-only.
-- All map onto the five the schema has and the detail stays in the
-- descriptions.
--
-- 167 stops, every one with a source.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('Devil’s Tramping Ground', 'devils-tramping-ground', 'folklore', 35.58432, -79.48702, 'Bear Creek', 'NC', 'A nearly circular patch of bare earth in the woods has carried a sinister reputation for generations. Folklore claims the Devil walks the circle at night and that objects placed inside may be moved or disturbed. The supernatural story is legend, but the strange clearing itself is a long-running North Carolina curiosity.', 'limited', 'https://www.visitnc.com/first-in-fright', null, 'America/New_York', now()),
  ('Brown Mountain Lights — Wiseman’s View', 'brown-mountain-lights-wisemans-view', 'ufos', 35.90383, -81.90476, 'Linville Falls', 'NC', 'Unexplained lights have been reported around Brown Mountain for more than a century, with theories ranging from atmospheric effects and vehicle lights to ghosts and UFOs. Wiseman’s View provides one of the best legitimate public viewpoints toward the mountain and is reached by a forest road that can be rough or seasonally affected. Viewing location: https://mapcarta.com/N356580279', 'limited', 'https://www.visitnc.com/itinerary/uncover-mountain-mysteries-north-carolinas-haunted-trail', null, 'America/New_York', now()),
  ('Judaculla Rock', 'judaculla-rock', 'folklore', 35.30093, -83.10986, 'Cullowhee', 'NC', 'This large soapstone boulder is covered with hundreds of ancient petroglyphs and is one of the most significant Native American rock-art sites in the Southeast. Cherokee tradition connects the stone with Judaculla, a powerful giant or supernatural being whose name is associated with the landscape.', 'open', 'https://www.visitnc.com/itinerary/uncover-mountain-mysteries-north-carolinas-haunted-trail', null, 'America/New_York', now()),
  ('St. John’s Episcopal Church — Demon Dogs of Valle Crucis', 'st-johns-episcopal-church-demon-dogs-of-valle-crucis', 'cryptids', 36.23199, -81.79873, 'Sugar Grove', 'NC', 'This historic mountain church is tied to the legend of the Demon Dogs of Valle Crucis: enormous spectral black dogs, sometimes described with glowing eyes, said to appear along the dark roads around the church. The haunting is folklore, but the church and cemetery are real historic sites and remain in use. Location source: https://mapcarta.com/21324918', 'limited', 'https://www.visitnc.com/itinerary/uncover-mountain-mysteries-north-carolinas-haunted-trail', null, 'America/New_York', now()),
  ('Museum of the Bizarre', 'museum-of-the-bizarre', 'museums', 34.23272, -77.94905, 'Wilmington', 'NC', 'Housed in an 1869 brick building near Wilmington’s riverfront, this museum mixes curiosities, unusual artifacts, movie props, true-crime material, strange machines, and sideshow-style displays. Exhibits have included a purported Houdini Ouija board, a crystal skull, and a Van de Graaff generator.', 'open', 'https://www.wilmingtonandbeaches.com/listing/museum-of-the-bizarre/1073/', 'https://museumbizarre.com/', 'America/New_York', now()),
  ('Cape Hatteras Lighthouse', 'cape-hatteras-lighthouse', 'haunted', 35.2512, -75.52818, 'Buxton', 'NC', 'The towering black-and-white spiral lighthouse is an Outer Banks icon and the tallest brick lighthouse in the United States. Its surrounding area also carries ghost stories, including tales of a spectral cat and maritime spirits linked with the dangerous waters of the Graveyard of the Atlantic.', 'limited', 'https://www.nps.gov/caha/planyourvisit/chls.htm', null, 'America/New_York', now()),
  ('Fort Raleigh National Historic Site — Lost Colony', 'fort-raleigh-national-historic-site-lost-colony', 'weird-history', 35.93694, -75.70896, 'Manteo', 'NC', 'Roanoke Island preserves the landscape associated with England’s first attempted permanent colony in North America. When a supply expedition returned in 1590, the settlers had vanished, leaving “CROATOAN” carved into a post. Their ultimate fate remains one of America’s best-known historical mysteries.', 'open', 'https://www.nps.gov/fora/index.htm', null, 'America/New_York', now()),
  ('Old Burying Ground — Rum Keg Girl', 'old-burying-ground-rum-keg-girl', 'folklore', 34.71857, -76.66357, 'Beaufort', 'NC', 'Beaufort’s old cemetery contains graves dating to the colonial period and several unusual burial stories. Its most famous legend concerns a young girl who died at sea and was supposedly preserved in a barrel of rum so her father could fulfill a promise to return her body home for burial.', 'limited', 'https://www.beauforthistoricsite.org/old-burying-ground/', null, 'America/New_York', now()),
  ('Grave of Wolfman Jack', 'grave-of-wolfman-jack', 'weird-history', 36.2683, -76.5473, 'Belvidere', 'NC', 'Legendary radio personality Wolfman Jack, born Robert Weston Smith, spent his final years in rural northeastern North Carolina and was buried near his Belvidere home after his death in 1995. The gravesite can be seen from the road, but it is associated with private family property, so this should remain a respectful roadside-view stop.', 'roadside', 'https://www.roadsideamerica.com/tip/latest', null, 'America/New_York', now()),
  ('Goldsboro Nuclear Mishap Historical Marker', 'goldsboro-nuclear-mishap-historical-marker', 'weird-history', 35.54197, -77.87647, 'Eureka', 'NC', 'A state historical marker recalls the 1961 crash of a B-52 carrying two hydrogen bombs near Goldsboro. Neither weapon produced a nuclear explosion, but declassified information later showed how close one bomb came to completing parts of its arming sequence.', 'roadside', 'https://www.hmdb.org/', null, 'America/New_York', now()),
  ('Last Shell Oil Clamshell Station', 'last-shell-oil-clamshell-station', 'roadside-oddities', 36.0677, -80.2141, 'Winston-Salem', 'NC', 'This restored 1930s service station is literally shaped like a giant yellow scallop shell. Quality Oil built several shell-shaped stations as advertising, but the Sprague Street building is the only surviving example and is now preserved as an architectural roadside oddity. Address: https://www.cityofws.org/DocumentCenter/View/25690', 'roadside', 'https://qualityoilnc.com/mural/', null, 'America/New_York', now()),
  ('World’s Largest Ten Commandments — Fields of the Wood', 'worlds-largest-ten-commandments-fields-of-the-wood', 'roadside-oddities', 35.12071, -84.25019, 'Murphy', 'NC', 'A massive rendering of the Ten Commandments covers a mountainside at Fields of the Wood, a religious park operated by the Church of God of Prophecy. Visitors can climb the hillside among enormous letters and other large-scale biblical monuments.', 'limited', 'https://www.roadsideamerica.com/location/nc', 'https://www.fieldsofthewoodbiblepark.com/', 'America/New_York', now()),
  ('Land of Oz', 'land-of-oz', 'weird-history', 36.211, -81.889, 'Beech Mountain', 'NC', 'This Wizard of Oz theme park opened in 1970 and later closed as a regular attraction, leaving behind a surreal mountaintop Yellow Brick Road, Dorothy’s farmhouse, and themed structures. It is not abandoned property open for exploration: the site operates through scheduled events and ticketed dates, and entering outside authorized events is trespassing. Visitor information: https://landofoznc.com/faq/', 'limited', 'https://landofoznc.com/', null, 'America/New_York', now()),
  ('Wheels Through Time Museum', 'wheels-through-time-museum', 'museums', 35.51372, -83.07695, 'Maggie Valley', 'NC', 'Hundreds of rare American motorcycles, automobiles, and machines fill this museum, with an emphasis on vehicles that still run rather than static restorations. The collection includes extremely early motorcycles, racing machines, military bikes, and unusual mechanical survivors.', 'limited', 'https://wheelsthroughtime.com/', null, 'America/New_York', now()),
  ('American Museum of the House Cat', 'american-museum-of-the-house-cat', 'museums', 35.31328, -83.2609, 'Sylva', 'NC', 'An entire museum is devoted to the domestic cat, with thousands of cat-related objects ranging from antique art and advertising to toys, carvings, clocks, and historic memorabilia. It is one of the most narrowly themed museums in the state.', 'limited', 'https://www.catman2.org/', null, 'America/New_York', now()),
  ('Cloud Chamber for the Trees and Sky', 'cloud-chamber-for-the-trees-and-sky', 'roadside-oddities', 35.80605, -78.69902, 'Raleigh', 'NC', 'Artist Chris Drury built this stone chamber at the North Carolina Museum of Art as a giant camera obscura. A small opening projects an upside-down moving image of the surrounding trees and sky onto the interior walls, turning the room itself into a simple optical machine. Museum: https://ncartmuseum.org/', 'open', 'https://www.atlasobscura.com/places/cloud-chamber-for-the-trees-and-sky', null, 'America/New_York', now()),
  ('Belhaven Memorial Museum', 'belhaven-memorial-museum', 'museums', 35.53914, -76.62153, 'Belhaven', 'NC', 'This old-school cabinet-of-curiosities museum grew from the collection of local resident Eva Blount Way. Its crowded displays include taxidermy, shells, dolls, antique tools, odd natural specimens, household objects, and miscellaneous artifacts gathered over decades.', 'limited', 'https://www.atlasobscura.com/places/belhaven-memorial-museum', null, 'America/New_York', now()),
  ('Aurora Fossil Museum & Fossil Pits', 'aurora-fossil-museum-fossil-pits', 'museums', 35.30461, -76.78771, 'Aurora', 'NC', 'The museum interprets the enormous fossil deposits exposed by phosphate mining in eastern North Carolina. Outdoor fossil pits allow visitors to sift through material for shark teeth and other marine fossils, turning the stop into a hands-on hunt for remnants of prehistoric oceans.', 'limited', 'https://aurorafossilmuseum.org/', null, 'America/New_York', now()),
  ('House of Mugs', 'house-of-mugs', 'roadside-oddities', 35.9585, -81.71102, 'Collettsville', 'NC', 'Thousands of coffee mugs cover the exterior walls, fences, trees, and outbuildings around this rural property, creating a dense folk-art environment assembled from ordinary cups. Visitors should follow the owners’ posted access expectations and treat it as a private-property attraction rather than a public park.', 'limited', 'https://www.atlasobscura.com/places/house-of-mugs', null, 'America/New_York', now()),
  ('Grave Digger’s Dungeon', 'grave-diggers-dungeon', 'roadside-oddities', 36.28542, -75.9198, 'Poplar Branch', 'NC', 'The home base of the Grave Digger monster truck has become a roadside attraction filled with retired trucks, memorabilia, displays, animals, and other motorsports oddities. Current operations also include monster-truck ride experiences on selected days.', 'open', 'https://www.diggersdungeon.com/', null, 'America/New_York', now()),
  ('North Carolina Taxidermy Hall of Fame, Creation Museum & Antique Tool Museum', 'north-carolina-taxidermy-hall-of-fame-creation-museum-antique-tool-museum', 'museums', 35.17465, -79.39135, 'Southern Pines', 'NC', 'Several highly unusual collections share this roadside museum complex, combining elaborate taxidermy, antique tools, and creationist displays under one roof. The mix makes it one of the stranger museum combinations in North Carolina. Current local listing: https://www.moorechoices.net/', 'limited', 'https://www.roadsideamerica.com/location/nc', null, 'America/New_York', now()),
  ('Madison Dry Goods & Country Store', 'madison-dry-goods-country-store', 'weird-history', 36.38773, -79.95987, 'Madison', 'NC', 'This old-fashioned general store includes a small upstairs museum with local artifacts and material connected to one of the area’s most notorious crimes, the 1929 Lawson family murders. The building has also become associated with ghost stories and paranormal investigations.', 'open', 'https://www.atlasobscura.com/places/madison-dry-goods', null, 'America/New_York', now()),
  ('The Road to Nowhere', 'the-road-to-nowhere', 'weird-history', 35.45906, -83.53803, 'Bryson City', 'NC', 'A mountain road built after the creation of Great Smoky Mountains National Park ends abruptly at a long tunnel through the mountain. Construction was abandoned before the promised route was completed, leaving a paved road and dark pedestrian-access tunnel that literally lead nowhere.', 'open', 'https://www.nps.gov/grsm/learn/historyculture/north-shore-road.htm', null, 'America/New_York', now()),
  ('Henry River Mill Village — District 12', 'henry-river-mill-village-district-12', 'weird-history', 35.69566, -81.42919, 'Hickory', 'NC', 'This preserved early-20th-century textile village became internationally recognizable after serving as District 12 in the first Hunger Games film. The property is privately operated and offers authorized tours; it should not be treated as an abandoned site open for unsupervised exploration. Location source: https://mapcarta.com/N9621020497', 'limited', 'https://henryrivermillvillage.com/', null, 'America/New_York', now()),
  ('Minnie Evans Bottle Chapel', 'minnie-evans-bottle-chapel', 'roadside-oddities', 34.2143, -77.8244, 'Wilmington', 'NC', 'At the Minnie Evans Sculpture Garden, a chapel-like structure made from colored bottles, cement, and found material honors visionary artist Minnie Evans. Sunlight passing through the bottles gives the small structure a stained-glass effect unlike a conventional garden sculpture.', 'limited', 'https://www.cameronartmuseum.org/', null, 'America/New_York', now()),
  ('Kindred Spirit Mailbox', 'kindred-spirit-mailbox', 'folklore', 33.86778, -78.53059, 'Sunset Beach', 'NC', 'A lone mailbox in the dunes of Bird Island has collected anonymous letters, confessions, wishes, and personal stories from visitors for decades. Reaching it requires a walk along the beach, and the notebooks inside have become a communal archive of strangers’ thoughts. Local information: https://www.sunsetbeachnc.gov/', 'limited', 'https://www.atlasobscura.com/places/kindred-spirit-mailbox', null, 'America/New_York', now()),
  ('British Cemetery', 'british-cemetery', 'weird-history', 35.116, -75.97295, 'Ocracoke', 'NC', 'Four British sailors killed when the HMT Bedfordshire was torpedoed by a German U-boat in 1942 are buried in this tiny cemetery on Ocracoke. The plot is maintained in honor of the men and is treated ceremonially as British soil.', 'open', 'https://www.nps.gov/caha/learn/historyculture/british-cemetery.htm', null, 'America/New_York', now()),
  ('Graveyard of the Atlantic Museum', 'graveyard-of-the-atlantic-museum', 'roadside-oddities', 35.20635, -75.70406, 'Hatteras', 'NC', 'This museum is dedicated to the thousands of shipwrecks, storms, wars, rescues, pirates, and maritime disasters associated with the dangerous waters off the Outer Banks. Its location near Hatteras Inlet puts it directly beside the landscape that earned the region the name “Graveyard of the Atlantic.”', 'limited', 'https://graveyardoftheatlantic.com/', null, 'America/New_York', now()),
  ('Andre the Giant Historical Marker', 'andre-the-giant-historical-marker', 'weird-history', 35.08927, -79.76253, 'Ellerbe', 'NC', 'A historical marker recognizes professional wrestling legend André René Roussimoff, better known as André the Giant, who owned a ranch outside Ellerbe and preferred the privacy of rural North Carolina when he was away from wrestling. The marker gives the state an unusually fitting memorial to a literal giant. Current listing: https://www.roadsideamerica.com/location/nc', 'roadside', 'https://www.hmdb.org/', null, 'America/New_York', now()),
  ('World’s Largest Strawberry', 'worlds-largest-strawberry', 'roadside-oddities', 35.04103, -79.76723, 'Ellerbe', 'NC', 'The Berry Patch is topped by an enormous strawberry-shaped building that functions as one of the most conspicuous roadside fruit monuments in the Carolinas. The giant berry advertises the farm market below it and is visible directly from the highway.', 'roadside', 'https://www.strangecarolinas.com/', null, 'America/New_York', now()),
  ('Shangri-La Stone Village', 'shangri-la-stone-village', 'roadside-oddities', 36.29968, -79.21458, 'Prospect Hill', 'NC', 'Retired tobacco farmer Henry Warren spent years constructing a miniature stone village beside his home. Tiny churches, theaters, homes, mills, and other buildings form a remarkably elaborate fantasy community made largely from local stone.', 'limited', 'https://www.atlasobscura.com/places/shangri-la-stone-village', null, 'America/New_York', now()),
  ('World’s Largest Operational Frying Pan', 'worlds-largest-operational-frying-pan', 'roadside-oddities', 34.82632, -78.02188, 'Rose Hill', 'NC', 'Rose Hill’s enormous frying pan was built to cook massive quantities of poultry during community events. Unlike many oversized roadside objects, this pan was designed to actually function, giving its “operational” claim a practical basis.', 'roadside', 'https://www.roadsideamerica.com/location/nc', null, 'America/New_York', now()),
  ('Museum of the Alphabet', 'museum-of-the-alphabet', 'museums', 34.86457, -80.74182, 'Waxhaw', 'NC', 'Created by JAARS, this specialized museum explores writing systems from around the world and the development of alphabets, scripts, printing, and language. Exhibits range from ancient systems to modern linguistic work, making written language itself the museum’s central artifact.', 'limited', 'https://www.jaars.org/visit/museum-of-the-alphabet/', null, 'America/New_York', now()),
  ('Grave of Chang and Eng Bunker', 'grave-of-chang-and-eng-bunker', 'weird-history', 36.45363, -80.62884, 'Mount Airy', 'NC', 'Chang and Eng Bunker, the conjoined twins whose fame popularized the term “Siamese twins,” settled in North Carolina, married sisters, raised large families, and became farmers. They are buried together beneath a shared marker in the White Plains Baptist Church cemetery.', 'open', 'https://www.atlasobscura.com/places/grave-of-chang-and-eng-bunker', null, 'America/New_York', now()),
  ('Graves of the McGuire Twins', 'graves-of-the-mcguire-twins', 'weird-history', 35.24562, -82.54773, 'Hendersonville', 'NC', 'Billy and Benny McCrary became internationally famous as the McGuire Twins, professional wrestlers and entertainers billed as the world’s heaviest twins. Their matching graves continue the pair’s visual symmetry even after death.', 'open', 'https://www.atlasobscura.com/places/grave-of-the-worlds-largest-twins', null, 'America/New_York', now()),
  ('Jackson Grave Houses', 'jackson-grave-houses', 'weird-history', 36.40305, -77.3767, 'Jackson', 'NC', 'Several graves in this eastern North Carolina cemetery are enclosed by small house-like wooden structures rather than ordinary markers alone. These “grave houses” preserve a burial tradition once found more widely in parts of the American South but now rarely seen.', 'open', 'https://www.atlasobscura.com/places/jackson-grave-houses', null, 'America/New_York', now()),
  ('Grave of Daisy and Violet Hilton', 'grave-of-daisy-and-violet-hilton', 'weird-history', 35.2578, -80.913, 'Charlotte', 'NC', 'Conjoined twins Daisy and Violet Hilton spent much of their lives performing in vaudeville, sideshows, and film before eventually settling in Charlotte. They died within days of one another during the 1968 flu pandemic and share a grave at Forest Lawn West Cemetery.', 'open', 'https://www.atlasobscura.com/places/daisy-and-violet-hilton-grave', null, 'America/New_York', now()),
  ('Mystery Hill', 'mystery-hill-blowing-rock', 'roadside-oddities', 36.1633, -81.64417, 'Blowing Rock', 'NC', 'This classic roadside “gravity hill” attraction has operated for decades around rooms and structures designed to distort visitors’ sense of level, balance, and gravity. The site has expanded with optical illusions, Appalachian exhibits, and other attractions while keeping the tilted Mystery House as its centerpiece. Location source: https://mapcarta.com/N2385806042', 'open', 'https://mysteryhill.com/', null, 'America/New_York', now()),
  ('Mile High Swinging Bridge', 'mile-high-swinging-bridge', 'roadside-oddities', 36.09505, -81.83224, 'Linville', 'NC', 'A suspension footbridge stretches across an exposed gap near the summit of Grandfather Mountain at roughly a mile above sea level. Wind and elevation make the crossing feel far more dramatic than its modest length suggests.', 'limited', 'https://grandfather.com/mile-high-swinging-bridge/', null, 'America/New_York', now()),
  ('Mary’s Gone Wild', 'marys-gone-wild', 'roadside-oddities', 33.93461, -78.29365, 'Supply', 'NC', 'Artist Mary Paulsen transformed her property into a dense environment of bottle houses, painted figures, dolls, recycled materials, signs, shrines, and handmade structures. The result is an intensely personal piece of outsider art that looks unlike almost anything else along the North Carolina coast. Location reference: https://www.strangecarolinas.com/', 'limited', 'https://www.roadsideamerica.com/tip/6636', null, 'America/New_York', now()),
  ('Thomas Wolfe’s Angel', 'thomas-wolfes-angel', 'roadside-oddities', 35.31933, -82.47518, 'Hendersonville', 'NC', 'A marble angel in Oakdale Cemetery became famous because of its association with Thomas Wolfe’s novel Look Homeward, Angel. The sculpture was carved in Italy and sold by Wolfe’s father, whose monument shop inspired major elements of the novel.', 'open', 'https://www.atlasobscura.com/places/thomas-wolfes-angel', null, 'America/New_York', now()),
  ('Vollis Simpson Whirligig Park', 'vollis-simpson-whirligig-park', 'roadside-oddities', 35.72268, -77.91245, 'Wilson', 'NC', 'More than two dozen enormous kinetic sculptures by North Carolina folk artist Vollis Simpson fill this downtown park. Built from salvaged industrial parts, reflectors, fans, gears, and metal scraps, the towering whirligigs spin and flash whenever the wind catches them. Archive: https://spacesarchives.org/explore/search-the-online-collection/vollis-simpson-whirligigs/', 'open', 'https://www.wilsonwhirligigpark.org/', null, 'America/New_York', now()),
  ('Lydia’s Bridge — Phantom Hitchhiker Marker', 'lydias-bridge-phantom-hitchhiker-marker', 'haunted', 35.99744, -79.92582, 'Jamestown', 'NC', 'The legend of Lydia tells of a young woman killed in a crash who later appears along the road asking motorists for a ride home, only to vanish before reaching her destination. A historical folklore marker now identifies the tradition near the bridge most often connected with the story.', 'roadside', 'https://www.wgpfoundation.org/historic-markers/lydias-bridge/', null, 'America/New_York', now()),
  ('Bostic Lincoln Center', 'bostic-lincoln-center', 'weird-history', 35.36208, -81.83539, 'Bostic', 'NC', 'This small museum examines a persistent local claim that Abraham Lincoln was actually born in western North Carolina rather than Kentucky. Mainstream historians reject the theory, but the center preserves the documents, oral traditions, and arguments behind one of the state’s stranger historical disputes.', 'limited', 'https://bosticlincolncenter.com/', null, 'America/New_York', now()),
  ('Körner’s Folly', 'k-rners-folly', 'roadside-oddities', 36.11522, -80.07876, 'Kernersville', 'NC', 'Artist and designer Jule Gilmer Körner created this wildly eccentric house as a showcase for his interior-design work. Its rooms differ dramatically in size and style, with odd stairways, decorative experiments, unusually low and high ceilings, and a private theater built into the house. Location source: https://www.wikizero.net/wiki/en/National_Register_of_Historic_Places_listings_in_Forsyth_County%2C_North_Carolina', 'limited', 'https://www.kornersfolly.org/', null, 'America/New_York', now()),
  ('Metalmorphosis — Giant Moving Head', 'metalmorphosis-giant-moving-head', 'roadside-oddities', 35.1511, -80.9477, 'Charlotte', 'NC', 'Czech artist David Černý created this enormous stainless-steel human head from multiple horizontal layers that independently rotate. As the sections move, the face repeatedly breaks apart into abstract forms and then reassembles. Official property information: https://www.whitehallcorporatecenter.com/metalmorphosis', 'open', 'https://www.roadsideamerica.com/location/nc', null, 'America/New_York', now()),
  ('Battleship North Carolina', 'battleship-north-carolina', 'haunted', 34.23645, -77.95424, 'Wilmington', 'NC', 'The World War II battleship North Carolina is preserved across the Cape Fear River from downtown Wilmington and can be explored through multiple decks, turrets, crew spaces, and machinery compartments. Along with its documented wartime history, the ship has a strong paranormal reputation and even hosts official paranormal-investigation programming. Paranormal program contact: https://battleshipnc.com/contact/', 'limited', 'https://battleshipnc.com/', null, 'America/New_York', now()),
  ('Q.J. Stephenson’s Earth Museum', 'qj-stephensons-earth-museum', 'roadside-oddities', 36.44883, -77.55425, 'Garysburg', 'NC', 'Folk artist, trapper, and fossil collector Q.J. Stephenson covered a small cinder-block museum with animal tracks, fossils, shells, artifacts, petrified wood, and bizarre handmade creatures. The privately owned site was restored after years of decline and remains viewable during daylight hours; be respectful of the surrounding residence.', 'open', 'https://www.roadsideamerica.com/story/15624', null, 'America/New_York', now()),
  ('Marvin Johnson Gourd Museum', 'marvin-johnson-gourd-museum', 'museums', 35.50759, -78.74051, 'Angier', 'NC', 'A room inside the Angier Public Library contains hundreds of gourds collected and decorated by Marvin Johnson, including vessels, instruments, carvings, and unusually shaped natural specimens. Ask library staff for access when the room is not otherwise in use.', 'limited', 'https://www.atlasobscura.com/places/gourd-museum-angier-north-carolina', null, 'America/New_York', now()),
  ('Dark & Deviant Oddities', 'dark-deviant-oddities', 'roadside-oddities', 35.5291, -82.5282, 'Asheville', 'NC', 'Tucked inside Valiant Inscriptions Tattoo Gallery, this collection specializes in wet specimens, taxidermy, bones, skulls, malformed animals, and other macabre curiosities. Displays have included a cyclops deer, six-legged calf, Fiji-mermaid-style specimen, and human skulls. Current address: https://porcupine-icosahedron-hjxm.squarespace.com/faq', 'open', 'https://www.darkdeviantoddities.com/about', null, 'America/New_York', now()),
  ('Billy Graham Library — Talking Cow', 'billy-graham-library-talking-cow', 'roadside-oddities', 35.19048, -80.90931, 'Charlotte', 'NC', 'Among the serious exhibits at the Billy Graham Library is an unexpectedly strange animatronic dairy cow named Bessie that talks about Graham’s childhood on a North Carolina farm. The contrast between the robot cow and the surrounding presidential and religious memorabilia makes this one of Charlotte’s odder museum details. Oddity reference: https://www.roadsideamerica.com/location/nc', 'limited', 'https://billygrahamlibrary.org/', null, 'America/New_York', now()),
  ('Ruby City Museum', 'ruby-city-museum', 'museums', 35.18228, -83.37888, 'Franklin', 'NC', 'Hidden inside a long-running gem shop is a free museum packed with minerals, fossils, artifacts, skulls, and unusual specimens. Highlights have included an enormous sapphire, a huge amethyst, fossilized dinosaur coprolite, and a purported shrunken head. Location: https://www.visitsmokies.org/listings/ruby-city-gems-minerals/', 'open', 'https://www.rubycity.com/home', null, 'America/New_York', now()),
  ('Country Doctor Museum', 'country-doctor-museum', 'museums', 35.77875, -78.12241, 'Bailey', 'NC', 'This museum preserves the tools and working world of rural physicians from the days of house calls, horse-drawn transportation, and small-town pharmacies. Antique surgical equipment, medical instruments, medicine bottles, and doctors’ vehicles make the collection unusually tangible.', 'limited', 'https://countrydoctormuseum.org/', null, 'America/New_York', now()),
  ('Andy Griffith Museum', 'andy-griffith-museum', 'roadside-oddities', 36.49822, -80.60878, 'Mount Airy', 'NC', 'Mount Airy’s museum preserves one of the largest collections of Andy Griffith memorabilia, much of it donated by Griffith’s longtime friend Emmett Forrest. Costumes, props, personal items, and television artifacts connect the real North Carolina town with the fictional Mayberry it helped inspire.', 'limited', 'https://www.surryarts.org/agmuseum/', null, 'America/New_York', now()),
  ('Aluminum Tree & Ornament Museum', 'aluminum-tree-ornament-museum', 'museums', 35.23458, -82.73771, 'Brevard', 'NC', 'ATOM is a seasonal pop-up museum devoted to vintage aluminum Christmas trees and the strange color wheels, ornaments, and decorations that accompanied them. The deliberately kitschy collection appears at the Transylvania Heritage Museum around the holiday season rather than operating year-round. Seasonal information: https://www.romanticasheville.com/aluminum_tree_museum.htm', 'limited', 'https://aluminumtrees.weebly.com/contact.html', null, 'America/New_York', now()),
  ('Santa’s Land Fun Park & Zoo', 'santas-land-fun-park-zoo', 'roadside-oddities', 35.4677, -83.26504, 'Cherokee', 'NC', 'This old-school Christmas amusement park has operated in the Smoky Mountains since the 1960s with Santa, rides, holiday displays, animals, and retro attractions. Its permanently festive setting feels particularly strange during warm-weather visits.', 'limited', 'https://santaslandnc.net/', null, 'America/New_York', now()),
  ('Tail of the Dragon — Tree of Shame', 'tail-of-the-dragon-tree-of-shame', 'roadside-oddities', 35.46672, -83.92025, 'Deals Gap', 'NC', 'The North Carolina end of the famous Tail of the Dragon sits beside the Tree of Shame, where broken motorcycle parts are hung as warnings and trophies from crashes on the road’s 318 curves. The famed 11-mile route continues into Tennessee; this pin marks the North Carolina gathering point and roadside display.', 'open', 'https://tailofthedragon.com/', null, 'America/New_York', now()),
  ('Duke Lemur Center', 'duke-lemur-center', 'roadside-oddities', 35.9942, -78.96247, 'Durham', 'NC', 'Duke University maintains the world’s largest population of lemurs outside Madagascar in a research and conservation center hidden in the woods near campus. Public visits are controlled through scheduled tours rather than ordinary zoo-style walk-in access.', 'limited', 'https://lemur.duke.edu/', null, 'America/New_York', now()),
  ('Old Brontosaurus & Dinosaur Trail', 'old-brontosaurus-dinosaur-trail', 'roadside-oddities', 36.0294, -78.89941, 'Durham', 'NC', 'The Museum of Life and Science preserves a vintage concrete dinosaur from an earlier era of roadside science attractions alongside a modern dinosaur trail. The surviving old Brontosaurus is especially appealing because it looks more like a mid-century monster than a scientifically current reconstruction. Museum: https://www.lifeandscience.org/visit/', 'limited', 'https://www.roadsideamerica.com/tip/3495', null, 'America/New_York', now()),
  ('V & E Simonetti Historic Tuba Collection', 'v-e-simonetti-historic-tuba-collection', 'museums', 35.98896, -78.92469, 'Durham', 'NC', 'Hundreds of tubas, sousaphones, euphoniums, helicons, and related brass instruments fill this specialized collection. The museum traces the evolution of low-brass instruments through examples that range from elegant antiques to huge and strangely shaped horns.', 'limited', 'https://simonettitubacollection.com/', null, 'America/New_York', now()),
  ('The Can Opener — Gregson Street Overpass', 'the-can-opener-gregson-street-overpass', 'roadside-oddities', 35.9992, -78.91004, 'Durham', 'NC', 'This railroad bridge became internet-famous for repeatedly peeling roofs from trucks that ignored its low-clearance warnings, earning nicknames including the “Can Opener.” The clearance has since been increased, but the bridge’s long catalog of recorded crashes remains part of Durham folklore.', 'open', 'https://www.atlasobscura.com/places/truck-decapitating-bridge', null, 'America/New_York', now()),
  ('Elsewhere Living Museum', 'elsewhere-living-museum', 'roadside-oddities', 36.06573, -79.79108, 'Greensboro', 'NC', 'A former three-story thrift store containing decades of accumulated merchandise was transformed into a living museum and artist residency where the old objects themselves become raw material for installations. Nothing about the building resembles a conventional gallery. Location: https://publicartgso.org/2018/06/12/elsewhere/', 'limited', 'https://www.elsewheremuseum.org/', null, 'America/New_York', now()),
  ('Linville Caverns', 'linville-caverns', 'roadside-oddities', 35.91919, -81.9388, 'Marion', 'NC', 'North Carolina’s only show cave leads visitors through narrow underground passages filled with mineral formations, pools, bats, and trout living in total darkness. Tours have operated here since the 1930s.', 'limited', 'https://linvillecaverns.com/', null, 'America/New_York', now()),
  ('Reed Gold Mine', 'reed-gold-mine', 'weird-history', 35.28459, -80.46451, 'Midland', 'NC', 'The first authenticated gold discovery in the United States occurred here after a 12-year-old found a large yellow rock that the family initially used as a doorstop. Visitors can tour portions of the underground mine and, seasonally, try gold panning.', 'limited', 'https://historicsites.nc.gov/all-sites/reed-gold-mine', null, 'America/New_York', now()),
  ('World’s Largest Highboy', 'worlds-largest-highboy', 'roadside-oddities', 35.97229, -79.92485, 'Jamestown', 'NC', 'Furnitureland South incorporates an enormous highboy dresser into its architecture, creating an approximately 85-foot monument to the Piedmont furniture industry. The giant drawers and broken-pediment top make the building look like furniture scaled for a giant.', 'roadside', 'https://www.roadsideamerica.com/story/15625', null, 'America/New_York', now()),
  ('Giant Legs of Ricky Pearce', 'giant-legs-of-ricky-pearce', 'roadside-oddities', 36.30071, -78.39951, 'Henderson', 'NC', 'A pair of enormous human legs stands upright beside a rural property, with no torso attached and little context for passing drivers. Artist Ricky Pearce created the surreal roadside sculpture, which looks like a giant has disappeared into the ground.', 'roadside', 'https://www.roadsideamerica.com/story/19708', null, 'America/New_York', now()),
  ('Moon-Eyed People Effigy', 'moon-eyed-people-effigy', 'folklore', 35.08674, -84.03294, 'Murphy', 'NC', 'The Cherokee County Historical Museum displays a small ancient soapstone figure popularly linked to the legend of the Moon-Eyed People, a mysterious group said in later folklore to have lived in the Appalachian region before Cherokee settlement. The artifact is real; its connection to the legendary people is speculative. Museum: https://www.cherokeecounty-nc.gov/183/Historical-Museum', 'limited', 'https://www.roadsideamerica.com/story/51476', null, 'America/New_York', now()),
  ('Firehorse Fred', 'firehorse-fred', 'weird-history', 35.10903, -77.04086, 'New Bern', 'NC', 'The preserved head of Fred, a New Bern fire horse who served the city in the early 1900s, is displayed at the New Bern Firemen’s Museum. According to museum history, Fred died while still harnessed after responding to what turned out to be a false alarm. Museum: https://newbernfiremuseum.com/', 'limited', 'https://www.roadsideamerica.com/story/2149', null, 'America/New_York', now()),
  ('Tombstone in the Middle of a Cotton Field', 'tombstone-in-the-middle-of-a-cotton-field', 'weird-history', 35.2117, -78.3473, 'Newton Grove', 'NC', 'A solitary grave marker for Adolphus Rob Lee stands isolated in an agricultural field rather than within a conventional cemetery. It is best viewed respectfully from legitimate roadside access without entering planted private land.', 'roadside', 'https://www.roadsideamerica.com/tip/21918', null, 'America/New_York', now()),
  ('Andrews Geyser', 'andrews-geyser', 'roadside-oddities', 35.65105, -82.24167, 'Old Fort', 'NC', 'Despite its name, this tall plume of water is not a natural geyser. The gravity-fed fountain was created as a railroad-era scenic feature and memorial, producing an unexpectedly dramatic jet of water against the mountain landscape when operating.', 'open', 'https://www.roadsideamerica.com/tip/19729', null, 'America/New_York', now()),
  ('Dinosaur Skeleton Sculptures', 'dinosaur-skeleton-sculptures', 'roadside-oddities', 35.4978, -77.9409, 'Pikeville', 'NC', 'Large steel dinosaur skeletons stand outside Benton & Sons Fabrication along NC 581, showing off the company’s metalworking skills in prehistoric form. Several of the skeletal creatures are illuminated or decorated during holiday periods. Address reference: https://www.osha.gov/ords/imis/establishment.inspection_detail?id=1369557.015', 'roadside', 'https://www.roadsideamerica.com/location/nc', null, 'America/New_York', now()),
  ('CSS Albemarle Replica', 'css-albemarle-replica', 'roadside-oddities', 35.86853, -76.74787, 'Plymouth', 'NC', 'A full-size floating replica of the Confederate ironclad CSS Albemarle sits beside the Port O’Plymouth Museum. The original armored vessel terrorized Union forces on eastern North Carolina rivers before being sunk by a daring torpedo attack in 1864. Location: https://www.waymarking.com/waymarks/wm17Z0H_The_Port_o_Plymouth_Museum_Plymouth_NC', 'limited', 'https://www.roadsideamerica.com/location/nc', null, 'America/New_York', now()),
  ('SECU Daily Planet — Giant Globe', 'secu-daily-planet-giant-globe', 'roadside-oddities', 35.7821, -78.63958, 'Raleigh', 'NC', 'A roughly three-story globe projects from the Nature Research Center of the North Carolina Museum of Natural Sciences. The giant Earth is not merely decoration: its interior contains a theater used for science programming. Museum: https://naturalsciences.org/', 'open', 'https://www.strangecarolinas.com/2015/01/secu-daily-planethuge-freakin-globe.html', null, 'America/New_York', now()),
  ('Raleigh Muffler Man — Giant Decorator', 'raleigh-muffler-man-giant-decorator', 'roadside-oddities', 35.88054, -78.57758, 'Raleigh', 'NC', 'A towering fiberglass Muffler Man stands on private commercial property near Overlook Road, repurposed from the classic roadside-advertising giant form. It is visible from public roads and should be treated strictly as a drive-by/photo stop.', 'private', 'https://www.roadsideamerica.com/location/nc', null, 'America/New_York', now()),
  ('Pine State Creamery Butter Churn', 'pine-state-creamery-butter-churn', 'roadside-oddities', 35.78566, -78.64674, 'Raleigh', 'NC', 'A giant concrete butter churn survives atop the former Pine State Creamery building, advertising the site’s dairy past long after the creamery itself disappeared. Its oversized handle makes the rooftop object particularly easy to spot.', 'roadside', 'https://www.atlasobscura.com/places/creamery-butter-churn', null, 'America/New_York', now()),
  ('Free Expression Tunnel', 'free-expression-tunnel', 'roadside-oddities', 35.78548, -78.67174, 'Raleigh', 'NC', 'North Carolina State University’s pedestrian tunnel has been a legal graffiti wall since the 1960s. Layers of paint change constantly as students cover old messages with art, jokes, announcements, memorials, and political commentary.', 'open', 'https://www.atlasobscura.com/places/free-expression-tunnel-at-nc-state', null, 'America/New_York', now()),
  ('Stanley Rehder Carnivorous Plant Garden', 'stanley-rehder-carnivorous-plant-garden', 'roadside-oddities', 34.20578, -77.90728, 'Wilmington', 'NC', 'A protected garden displays native Venus flytraps, pitcher plants, sundews, and other carnivorous species in the region where Venus flytraps naturally occur. The site was also targeted in a notorious flytrap theft that helped draw attention to stronger legal protections for the plants. Current city programming: https://www.wilmingtonnc.gov/Events-directory/Flytrap-Frolic', 'open', 'https://www.atlasobscura.com/places/stanley-rehder-carnivorous-plant-garden', null, 'America/New_York', now()),
  ('Pachinko World', 'pachinko-world', 'museums', 34.19477, -77.91997, 'Wilmington', 'NC', 'This unusual arcade focuses on Japanese pachinko machines, combining playable vintage machines with other retro games and memorabilia. The dense rows of flashing vertical games look very different from a standard American arcade.', 'open', 'https://www.atlasobscura.com/places/pachinko-world', null, 'America/New_York', now()),
  ('Brunswick Town / Fort Anderson', 'brunswick-town-fort-anderson', 'weird-history', 34.04045, -77.94617, 'Winnabow', 'NC', 'The ruins of a colonial port town sit beneath and around a later Confederate fort on the Cape Fear River. Excavated foundations, old streets, earthworks, and the surviving shell of St. Philip’s Church give the site the feel of multiple abandoned eras stacked on top of one another. Official site: https://historicsites.nc.gov/all-sites/brunswick-town-fort-anderson', 'limited', 'https://www.atlasobscura.com/places/brunswick-townfort-anderson', null, 'America/New_York', now()),
  ('Grave of Robert E. Harrill — The Fort Fisher Hermit', 'grave-of-robert-e-harrill-the-fort-fisher-hermit', 'weird-history', 34.01798, -77.91458, 'Carolina Beach', 'NC', 'Robert E. Harrill became a coastal celebrity after living for years in an abandoned World War II bunker near Fort Fisher and welcoming thousands of curious visitors. His grave preserves the story of the self-styled Fort Fisher Hermit after his mysterious death in 1972.', 'open', 'https://www.atlasobscura.com/places/newton-graveyard-and-homesite', null, 'America/New_York', now()),
  ('Grahamland Attractions', 'grahamland-attractions', 'roadside-oddities', 34.31711, -78.24314, 'Bolton', 'NC', 'A sprawling private folk-art environment contains hundreds of fiberglass animals, cartoon figures, giant characters, statues, and repurposed roadside objects. The collection feels like pieces of several extinct amusement parks gathered into one rural property.', 'limited', 'https://www.atlasobscura.com/places/grahamland-attractions-north-carolina', null, 'America/New_York', now()),
  ('Queen Anne’s Revenge Artifacts — North Carolina Maritime Museum', 'queen-annes-revenge-artifacts-north-carolina-maritime-museum', 'weird-history', 34.71767, -76.66704, 'Beaufort', 'NC', 'Artifacts recovered from the wreck believed to be Blackbeard’s flagship Queen Anne’s Revenge are displayed at the North Carolina Maritime Museum. Cannons, medical equipment, navigational objects, and everyday shipboard finds give the famous pirate a physical archaeological footprint. Artifact project: https://www.qaronline.org/', 'limited', 'https://ncmaritimemuseumbeaufort.com/', null, 'America/New_York', now()),
  ('North Carolina Transportation Museum', 'north-carolina-transportation-museum', 'roadside-oddities', 35.68718, -80.4347, 'Spencer', 'NC', 'A former Southern Railway repair complex now holds locomotives, railcars, automobiles, aircraft, and other transportation artifacts. Its enormous surviving roundhouse and working turntable make the industrial site as interesting as the collection.', 'limited', 'https://www.nctransportationmuseum.org/', null, 'America/New_York', now()),
  ('Paul Bunyan & Babe the Blue Ox — Log Cabin Homes', 'paul-bunyan-babe-the-blue-ox-log-cabin-homes', 'roadside-oddities', 36.0439, -77.8439, 'Battleboro', 'NC', 'A towering fiberglass Paul Bunyan stands beside Interstate 95 at a log-home sales center, accompanied by Babe the Blue Ox. The figure began life as a classic Muffler Man and was later transformed into a lumberjack advertising landmark. Current business: https://www.logcabinhomes.com/', 'roadside', 'https://www.roadsideamerica.com/tip/8857', null, 'America/New_York', now()),
  ('Wilson Muffler Man', 'wilson-muffler-man', 'roadside-oddities', 35.7168, -77.90636, 'Wilson', 'NC', 'A classic fiberglass advertising giant stands outside White’s Tire Service holding a tire and waving to passing traffic. It is one of the surviving examples of the mass-produced Muffler Men that once lined American highways. Location: https://www.whitestireservice.com/Contact/Find-Us', 'roadside', 'https://www.roadsideamerica.com/location/nc', null, 'America/New_York', now()),
  ('Historic Salvo Post Office', 'historic-salvo-post-office', 'roadside-oddities', 35.54, -75.47417, 'Salvo', 'NC', 'This tiny historic post-office building measures only about eight by twelve feet and once served one of the Outer Banks’ small communities. It no longer provides postal service but has been preserved as a roadside landmark and is listed on the National Register of Historic Places. Historic coordinates: https://en.chped.com/wiki/National_Register_of_Historic_Places_listings_in_Dare_County%2C_North_Carolina', 'roadside', 'https://www.roadsideamerica.com/tip/27430', null, 'America/New_York', now()),
  ('Children’s Shoe House', 'childrens-shoe-house', 'roadside-oddities', 35.4615, -81.2816, 'Lincolnton', 'NC', 'A small building shaped like a giant child’s shoe sits in the yard at the historic Woodside property, birthplace of Texas’s first governor, James Pinckney Henderson. The property is private, and recent 2026 reports confirm the shoe is still visible from the road. Historic property reference: https://lincolncountyhistory.com/national-registry-of-historic-places/', 'private', 'https://www.roadsideamerica.com/tip/23004', null, 'America/New_York', now()),
  ('Restored 1953 Sinclair Gas Station', 'restored-1953-sinclair-gas-station', 'roadside-oddities', 35.2016, -83.8229, 'Andrews', 'NC', 'A vintage Sinclair service station was restored in 2025 with period pumps, signage, and the brand’s familiar green dinosaur imagery. It no longer operates as a normal gas station, making it more of a preserved roadside time capsule and photo stop. Restoration background: https://towns-and-nature.blogspot.com/2025/11/andrews-nc-old-sinclair-gas-station.html', 'roadside', 'https://www.roadsideamerica.com/location/nc', null, 'America/New_York', now()),
  ('Grave of Millie-Christine McKoy', 'grave-of-millie-christine-mckoy', 'weird-history', 34.38772, -78.66041, 'Whiteville', 'NC', 'Conjoined twins Millie and Christine McKoy were born enslaved in North Carolina in 1851 and later became internationally known performers billed as the “Two-Headed Nightingale.” Their shared grave in Welches Creek Cemetery bears an inscription describing “two hearts that beat as one.” Cemetery coordinates: https://www.wikidata.org/wiki/Q68101741', 'open', 'https://www.roadsideamerica.com/tip/47271', null, 'America/New_York', now()),
  ('Souvenir Shop Gator', 'souvenir-shop-gator', 'roadside-oddities', 34.44613, -77.5614, 'Surf City', 'NC', 'Visitors enter this beach souvenir store through the open jaws of a gigantic alligator facade. The oversized reptile turns an otherwise ordinary coastal shop into a classic piece of tourist-strip roadside architecture. Current business location: https://us.nextdoor.com/pages/waves-surf-sport-holly-ridge-nc/', 'open', 'https://www.roadsideamerica.com/location/nc', null, 'America/New_York', now()),
  ('Giant Shark Entrance', 'giant-shark-entrance', 'roadside-oddities', 34.52658, -77.43444, 'Sneads Ferry', 'NC', 'Shark Attack Souvenirs requires shoppers to walk directly through the open mouth of a huge fiberglass shark. The giant jaws remain one of the most blatant and effective examples of coastal roadside architecture in the state. Current location: https://nextdoor.com/pages/shark-attack-souvenir-gift-shop-sneads-ferry-nc/', 'open', 'https://www.roadsideamerica.com/tip/30533', null, 'America/New_York', now()),
  ('Hillside of Concrete Statues — Slick’s Pottery', 'hillside-of-concrete-statues-slicks-pottery', 'roadside-oddities', 36.53671, -80.51104, 'Mount Airy', 'NC', 'A hillside beside Slick’s Pottery is crowded with concrete animals, people, religious figures, fountains, and assorted lawn statues. Seen together, the inventory resembles an army of stone creatures gathering along the road. Location: https://nextdoor.com/pages/slicks-pottery-mount-airy-nc/', 'open', 'https://www.roadsideamerica.com/story/33938', null, 'America/New_York', now()),
  ('Brady C. Jefcoat Museum of Americana', 'brady-c-jefcoat-museum-of-americana', 'museums', 36.43995, -77.10222, 'Murfreesboro', 'NC', 'More than 13,000 everyday objects fill an old high school, including huge collections of washing machines, irons, phonographs, radios, mousetraps, tools, furniture, and household devices. The scale turns ordinary domestic objects into an overwhelming cabinet of American material culture. Location: https://mapcarta.com/W1192052560', 'limited', 'https://www.visitnc.com/brady-c-jefcoat-museum-americana', null, 'America/New_York', now()),
  ('King Neptune', 'king-neptune', 'roadside-oddities', 34.71953, -76.71281, 'Morehead City', 'NC', 'A giant, brightly painted King Neptune rises from the waterfront near Shepard Street, while his oversized mermaid-like tail appears separately behind him. The deliberately theatrical sea god has become a longtime fixture of downtown Morehead City’s docks. Coordinates: https://fotospot.com/attractions/north-carolina/goofy-king-neptune-statue', 'open', 'https://www.roadsideamerica.com/tip/29124', null, 'America/New_York', now()),
  ('Asheville Pinball Museum', 'asheville-pinball-museum', 'museums', 35.59646, -82.55694, 'Asheville', 'NC', 'Rows of playable pinball machines and classic arcade cabinets turn this museum into an interactive history of coin-operated games. Admission typically allows visitors to play rather than merely look at the machines behind barriers.', 'open', 'https://www.atlasobscura.com/places/asheville-pinball-museum', null, 'America/New_York', now()),
  ('Moogseum', 'moogseum', 'museums', 35.59729, -82.55216, 'Asheville', 'NC', 'Dedicated to synthesizer pioneer Bob Moog, this museum combines music history with hands-on electronic experiments, prototypes, instruments, and an interactive theremin. Exhibits explain how electrical signals are transformed into the strange sounds that made Moog synthesizers famous.', 'limited', 'https://www.atlasobscura.com/places/moogseum', 'https://moogseum.org/', 'America/New_York', now()),
  ('Helen’s Bridge', 'helens-bridge', 'haunted', 35.59547, -82.53806, 'Asheville', 'NC', 'A stone bridge built in 1909 near the Zealandia mansion is tied to one of Asheville’s best-known ghost legends. Folklore says a grieving woman named Helen hanged herself here after losing her daughter and still appears around the bridge; the story is unverified, and visitors should stay on public roads and away from the private mansion. Coordinates: https://maps.apple.com/place?place-id=I380314F2E1C7A93', 'roadside', 'https://www.atlasobscura.com/places/helen-s-bridge', null, 'America/New_York', now()),
  ('McCandless Collection', 'mccandless-collection', 'museums', 36.05843, -79.445, 'Burlington', 'NC', 'This appointment-only museum is packed with rare Mopar vehicles, historic race cars, vintage signs, clocks, and automobilia. The collection focuses heavily on the Forward Look era and American automotive history, making it much more specialized than a general car museum.', 'limited', 'https://www.atlasobscura.com/places/mccandless-collection', 'https://www.mccandlesscollection.com/', 'America/New_York', now()),
  ('WPTF AM Radio Building', 'wptf-am-radio-building', 'weird-history', 35.79107, -78.76113, 'Cary', 'NC', 'This 1930s AM transmitter building is still in operation, but its newer claim to OddWay fame is television: it inspired the WSQK radio station building seen in the final season of Stranger Things. The building itself is across from the listed roadside viewing point and is not a public attraction to enter.', 'roadside', 'https://www.atlasobscura.com/places/wptf-am-radio-building', null, 'America/New_York', now()),
  ('Morris the Horse', 'morris-the-horse', 'roadside-oddities', 35.20865, -82.23823, 'Tryon', 'NC', 'A giant fiberglass horse has represented Tryon’s equestrian and toy-making history for generations. The original wooden Morris was created for a 1928 horse show; the current figure is the fourth version after earlier horses met unusually destructive ends. Local source: https://exploretryon.com/business-listings/morris-the-horse/', 'open', 'https://www.atlasobscura.com/places/morris-the-horse', null, 'America/New_York', now()),
  ('Memory Wall of Love and Peace', 'memory-wall-of-love-and-peace', 'roadside-oddities', 36.09903, -80.24568, 'Winston-Salem', 'NC', 'Artist Gregory Warmack, better known as Mr. Imagination, created this community folk-art wall from concrete, found objects, personal keepsakes, and sculpted figures. After years of deterioration, the installation was extensively restored and remains an unusual public memorial built partly from objects contributed by local residents.', 'open', 'https://www.atlasobscura.com/places/memory-wall-of-love-and-peace', null, 'America/New_York', now()),
  ('Martin Luther Statue', 'martin-luther-statue', 'roadside-oddities', 35.74143, -81.32622, 'Hickory', 'NC', 'A 12-foot granite Martin Luther stands on the campus of Lenoir-Rhyne University atop an additional four-foot pedestal. Atlas Obscura describes it as the largest stone statue of Luther in North America, giving the campus an unexpectedly monumental Reformation landmark.', 'open', 'https://www.atlasobscura.com/places/the-martin-luther-statue', null, 'America/New_York', now()),
  ('Scottish Tartans Museum', 'scottish-tartans-museum', 'museums', 35.18213, -83.37962, 'Franklin', 'NC', 'The only museum of its kind in the United States is devoted to tartans, kilts, Highland dress, weaving, Scottish weaponry, and Scottish migration to the Carolinas. Its collection includes centuries-old tartan samples and hundreds of patterns.', 'open', 'https://www.atlasobscura.com/places/scottish-tartans-museum', 'https://scottishtartansmuseum.org/', 'America/New_York', now()),
  ('Nuclear Cruise Missile in a Church Parking Lot', 'nuclear-cruise-missile-in-a-church-parking-lot', 'roadside-oddities', 35.48608, -77.90059, 'Pikeville', 'NC', 'A decommissioned TM-61C Matador cruise missile stands outside a church on land formerly associated with a private airstrip and restaurant. The weapon type was designed to carry a nuclear warhead, making the forty-foot missile an unusually ominous piece of roadside advertising history.', 'roadside', 'https://www.atlasobscura.com/places/cruise-missile-in-a-parking-lot', null, 'America/New_York', now()),
  ('Pepsi Inventor Caleb Bradham’s Grave', 'pepsi-inventor-caleb-bradhams-grave', 'weird-history', 35.114, -77.04399, 'New Bern', 'NC', 'Caleb Bradham created the drink that became Pepsi-Cola at his New Bern pharmacy before losing control of the company after a disastrous sugar-market gamble. His surprisingly modest grave lies in Cedar Grove Cemetery only a short distance from Pepsi’s birthplace.', 'open', 'https://www.atlasobscura.com/places/pepsi-inventor-caleb-bradham-s-grave', null, 'America/New_York', now()),
  ('Biltmore Estate’s Secret Passages', 'biltmore-estates-secret-passages', 'roadside-oddities', 35.56703, -82.54425, 'Asheville', 'NC', 'The enormous Biltmore mansion hides disguised doors, servant passages, concealed rooms, a library passageway, a trap door, and other architectural tricks. Not every hidden area is included on every tour, so visitors specifically interested in the secret spaces should check current tour offerings.', 'limited', 'https://www.atlasobscura.com/places/biltmore-secret-doors-hidden-passages', 'https://www.biltmore.com/', 'America/New_York', now()),
  ('Sliding Rock', 'sliding-rock', 'roadside-oddities', 35.31147, -82.78758, 'Pisgah Forest', 'NC', 'A smooth 60-foot rock face functions as a natural waterslide as thousands of gallons of cold mountain water rush over it each minute. Visitors can slide down the rock into the pool below when conditions and seasonal operations allow.', 'limited', 'https://www.atlasobscura.com/places/sliding-rock', null, 'America/New_York', now()),
  ('Kuwohi — Home of the Chief of All Bears', 'kuwohi-home-of-the-chief-of-all-bears', 'folklore', 35.56293, -83.49845, 'Bryson City', 'NC', 'At 6,644 feet, Kuwohi is the highest point in Great Smoky Mountains National Park and carries deep Cherokee cultural significance. Cherokee tradition associates the mountain with White Bear, chief of all bears, and with a sacred place where bears could heal; the former name Clingmans Dome was officially changed back to Kuwohi in 2024.', 'limited', 'https://www.atlasobscura.com/places/kuwohi-clingmans-dome', null, 'America/New_York', now()),
  ('The Fugitive Train Wreck', 'the-fugitive-train-wreck', 'weird-history', 35.37043, -83.26325, 'Sylva', 'NC', 'Rusting train and bus wreckage from the practical-effects crash sequence in the 1993 film The Fugitive still sits beside the Great Smoky Mountains Railroad. The wreckage is on railroad property and trespassing is prohibited; it can be viewed from legitimate public areas or from the railroad’s Tuckasegee River excursion.', 'private', 'https://www.atlasobscura.com/places/the-fugitive-train-wreck', null, 'America/New_York', now()),
  ('Bunker Hill Covered Bridge', 'bunker-hill-covered-bridge', 'roadside-oddities', 35.72155, -81.11525, 'Claremont', 'NC', 'Built in the 1890s, this pedestrian-only covered bridge is one of only two surviving covered bridges in North Carolina and is recognized as a National Civil Engineering Landmark. Its lattice-truss structure survives in a wooded setting over Lyle Creek.', 'open', 'https://www.atlasobscura.com/places/the-bunker-hill-covered-bridge-claremont-north-carolina', null, 'America/New_York', now()),
  ('Brevard White Squirrels', 'brevard-white-squirrels', 'roadside-oddities', 35.23345, -82.73429, 'Brevard', 'NC', 'Brevard is famous for a population of white Eastern gray squirrels that are not true albinos. Local lore traces the population to two pale squirrels connected with a traveling carnival in the late 1940s; the Brevard College campus is one of the better places to look for them.', 'open', 'https://www.atlasobscura.com/places/brevard-white-squirrels', null, 'America/New_York', now()),
  ('Looking Glass Rock', 'looking-glass-rock', 'roadside-oddities', 35.30372, -82.79346, 'Brevard', 'NC', 'This enormous exposed granite pluton rises abruptly from Pisgah National Forest like a giant stone dome. Its name comes from the way water or ice on the rock face can reflect sunlight, while the unusually sheer formation has also become a major climbing landmark.', 'limited', 'https://www.atlasobscura.com/places/looking-glass-rock', null, 'America/New_York', now()),
  ('Bare Dark Sky Observatory', 'bare-dark-sky-observatory', 'museums', 35.9305, -82.18247, 'Burnsville', 'NC', 'The Mayland Earth to Sky Park became the first certified International Dark Sky Park in the southeastern United States. Its observatory hosts scheduled astronomy programs in a mountain location selected specifically for exceptionally dark skies.', 'limited', 'https://www.atlasobscura.com/places/bare-dark-sky-observatory', 'https://www.mayland.edu/foundation/foundation-events/earth-to-sky-observatory/', 'America/New_York', now()),
  ('Endor Iron Furnace', 'endor-iron-furnace', 'weird-history', 35.55318, -79.21876, 'Cumnock', 'NC', 'A massive stone furnace built during the Civil War still stands near the Deep River. The short-lived industrial site once smelted local iron ore and today survives as a striking isolated ruin from North Carolina’s early heavy industry.', 'limited', 'https://carolinageologicalsociety.org/2010s_files/gb%202011.pdf', null, 'America/New_York', now()),
  ('Graylyn Estate', 'graylyn-estate', 'roadside-oddities', 36.11807, -80.28332, 'Winston-Salem', 'NC', 'This sprawling 1930s estate looks more like a transplanted European manor than a North Carolina mansion. Its 60-room design mixes medieval and Renaissance influences with extravagant details including marble tubs, gold fixtures, numerous radios, and showers originally fitted with 17 heads. Current tours: https://www.visitwinstonsalem.com/event/tour-pour-du-jour-graylyn-estate-1', 'limited', 'https://www.atlasobscura.com/places/graylyn', null, 'America/New_York', now()),
  ('Old Salem Coffee Pot', 'old-salem-coffee-pot', 'roadside-oddities', 36.0908, -80.2428, 'Winston-Salem', 'NC', 'A giant metal coffee pot has been a Winston-Salem landmark since the 1800s. Originally built as advertising for a tinsmith business, the oversized pot survived relocation and generations of local folklore to become one of the city’s oldest roadside oddities.', 'open', 'https://www.atlasobscura.com/things-to-do/north-carolina/places?page=4', null, 'America/New_York', now()),
  ('Cameron Barnstormer Murals', 'cameron-barnstormer-murals', 'roadside-oddities', 35.32682, -79.2553, 'Cameron', 'NC', 'Beginning in 1999, artists from New York and Tokyo covered aging tobacco barns and farm equipment around Cameron with large contemporary murals. Some of the barns have disappeared, but surviving examples turn the rural landscape into a fading open-air graffiti gallery.', 'roadside', 'https://www.atlasobscura.com/places/cameron-barnstormer-murals', null, 'America/New_York', now()),
  ('Frying Pan Tower', 'frying-pan-tower', 'roadside-oddities', 33.48333, -77.58333, 'Southport', 'NC', 'Far offshore from North Carolina, an old Coast Guard light station rises from the ocean like a rusting oil rig. The decommissioned platform has been privately restored and is not a casual roadside stop; visits require arranged boat, helicopter, or special access.', 'limited', 'https://www.atlasobscura.com/places/frying-pan-tower', 'https://fptower.org/', 'America/New_York', now()),
  ('Old Carbonton Dam Powerhouse', 'old-carbonton-dam-powerhouse', 'weird-history', 35.52043, -79.34891, 'Sanford', 'NC', 'Most of the Carbonton Dam was removed to restore the Deep River, but a tall abandoned concrete powerhouse was left behind beside a small public recreation area. The graffiti-covered shell now stands as an eerie industrial remnant beside the restored river.', 'open', 'https://www.atlasobscura.com/places/old-carbonton-dam', null, 'America/New_York', now()),
  ('Portsmouth Village Ghost Town', 'portsmouth-village-ghost-town', 'weird-history', 35.04835, -76.0798, 'Ocracoke', 'NC', 'Once an important Outer Banks shipping settlement, Portsmouth declined after hurricanes, shifting inlets, war, and isolation undermined the village. Its final residents left in 1971, leaving a collection of preserved houses, church, post office, and other structures on a remote island reached by boat. NPS: https://www.nps.gov/calo/learn/historyculture/portsmouth.htm', 'limited', 'https://www.atlasobscura.com/places/portsmouth-village', null, 'America/New_York', now()),
  ('Nina Simone’s Childhood Home', 'nina-simones-childhood-home', 'weird-history', 35.21385, -82.23216, 'Tryon', 'NC', 'A modest three-room wooden house is where Eunice Kathleen Waymon, later known as Nina Simone, spent part of her childhood and began playing piano at an exceptionally young age. The historically significant home has been preserved through an artist-led effort rather than turned into a conventional museum.', 'roadside', 'https://www.atlasobscura.com/places/nina-simone-childhood-home', null, 'America/New_York', now()),
  ('Homeless Jesus', 'homeless-jesus', 'roadside-oddities', 35.49359, -80.83224, 'Davidson', 'NC', 'A bronze sculpture depicts Jesus as an anonymous homeless person sleeping beneath a blanket on a park bench, recognizable primarily by the wounds on his feet. The installation initially startled residents who mistook the figure for an actual person sleeping outside the church.', 'open', 'https://www.atlasobscura.com/places/homeless-jesus', null, 'America/New_York', now()),
  ('Graveyard Island', 'graveyard-island', 'weird-history', 35.45801, -80.12372, 'Badin', 'NC', 'When the Yadkin River was dammed to create Badin Lake, hundreds of graves from threatened cemeteries were relocated to higher ground on what became an island. Roughly 300 burials are associated with the site, including marked and unmarked graves; portions have access restrictions, so visitors must respect posted rules and obtain permission where required.', 'limited', 'https://www.atlasobscura.com/places/graveyard-island', null, 'America/New_York', now()),
  ('Jockey’s Ridge', 'jockeys-ridge', 'roadside-oddities', 35.96241, -75.6339, 'Nags Head', 'NC', 'A huge field of shifting sand rises unexpectedly in the Outer Banks, forming the tallest active natural sand-dune system in the eastern United States. The landscape can feel like a small desert despite sitting between maritime forest and the Atlantic coast.', 'open', 'https://www.atlasobscura.com/places/jockey-s-ridge', null, 'America/New_York', now()),
  ('Peace Gardens & Market', 'peace-gardens-market', 'roadside-oddities', 35.58286, -82.58502, 'Asheville', 'NC', 'This community garden doubles as a dense found-object art environment filled with sculptures, paintings, reclaimed materials, and tributes to major figures in Black history. Food-growing spaces, art, neighborhood history, and environmental work are intentionally mixed together.', 'limited', 'https://www.atlasobscura.com/places/burton-street-community-peace-gardens', null, 'America/New_York', now()),
  ('Grimshawes Post Office', 'grimshawes-post-office', 'roadside-oddities', 35.0664, -83.1199, 'Cashiers', 'NC', 'This tiny wooden post-office building measures only about five by six feet and is commonly described as the smallest historic post office in the United States. Its miniature scale makes it look more like a shed or playhouse than functioning postal architecture.', 'limited', 'https://www.atlasobscura.com/things-to-do/north-carolina/places?page=5', null, 'America/New_York', now()),
  ('Lake Norman — “Normie” Monster', 'lake-norman-normie-monster', 'cryptids', 35.67213, -80.93259, 'Troutman', 'NC', 'North Carolina’s largest manmade lake has its own Nessie-style monster known as Normie. Reports collected over the years describe large wakes, unexplained splashes, and creatures compared with giant fish, crocodilians, or serpentine lake monsters; the pin uses Lake Norman State Park as a legitimate public access point.', 'open', 'https://www.atlasobscura.com/places/lake-norman', null, 'America/New_York', now()),
  ('Ancient Dugout Canoes at Lake Phelps', 'ancient-dugout-canoes-at-lake-phelps', 'weird-history', 35.7962, -76.421, 'Creswell', 'NC', 'Lake Phelps concealed an extraordinary archaeological record beneath its water: dozens of ancient Native American dugout canoes have been discovered in and around the lake. Pettigrew State Park interprets these finds and the long human history surrounding the unusual shallow lake.', 'limited', 'https://www.atlasobscura.com/things-to-do/north-carolina/lakes', null, 'America/New_York', now()),
  ('Geodetic Survey Stones', 'geodetic-survey-stones', 'museums', 35.78044, -78.63995, 'Raleigh', 'NC', 'A small arrangement of precisely placed stones on the State Capitol grounds looks like a miniature Stonehenge. The stones mark an 1850s geodetic experiment that used star observations, telegraph communication, and simultaneous measurements to establish accurate latitude and longitude.', 'open', 'https://www.atlasobscura.com/places/geodetic-survey-stones', null, 'America/New_York', now()),
  ('Wade Avenue Pumping Station “House”', 'wade-avenue-pumping-station-house', 'roadside-oddities', 35.8006, -78.67835, 'Raleigh', 'NC', 'This convincing suburban-looking house has shutters, columns, and a front-door facade, but no one lives inside. The city deliberately disguised a noisy municipal water pumping station as a residence to make the industrial facility blend into the neighborhood.', 'roadside', 'https://www.atlasobscura.com/places/pumping-station-house', null, 'America/New_York', now()),
  ('Alluvial Decoder at Crabtree Creek', 'alluvial-decoder-at-crabtree-creek', 'roadside-oddities', 35.83698, -78.67369, 'Raleigh', 'NC', 'A series of colorful poles along the greenway marks the heights reached by historic floods in Raleigh. A decoder beneath the bridge identifies the storms represented, turning destructive flood levels into a strange walk-through data visualization.', 'open', 'https://www.atlasobscura.com/places/alluvial-decoder-crabtree-creek', null, 'America/New_York', now()),
  ('Hatteras Weather Bureau Station', 'hatteras-weather-bureau-station', 'weird-history', 35.22022, -75.69044, 'Hatteras', 'NC', 'This bright historic weather station has an unexpected connection to the Titanic disaster. Operators here received early wireless information about the ship striking an iceberg in April 1912; the building later became a preserved National Park Service site and visitor facility. NPS: https://www.nps.gov/caha/planyourvisit/uswbs.htm', 'limited', 'https://www.atlasobscura.com/places/hatteras-weather-bureau-station', null, 'America/New_York', now()),
  ('International Lineman Museum', 'international-lineman-museum', 'museums', 35.25624, -81.48236, 'Shelby', 'NC', 'A museum devoted entirely to electrical lineworkers preserves old climbing equipment, hot sticks, pliers, insulators, meter boxes, cutouts, and even the upper portion of an early-1900s utility pole. It turns a profession most travelers rarely think about into a specialized historical collection.', 'limited', 'https://www.atlasobscura.com/places/international-lineman-museum', null, 'America/New_York', now()),
  ('Fort Dobbs', 'fort-dobbs', 'roadside-oddities', 35.82164, -80.89737, 'Statesville', 'NC', 'Archaeology allowed historians to reconstruct North Carolina’s only preserved French and Indian War fort on its original site. Costumed interpretation and a full-scale fortified barracks recreate the frontier outpost that was attacked during the Anglo-Cherokee War. Official site: https://historicsites.nc.gov/all-sites/fort-dobbs', 'limited', 'https://www.atlasobscura.com/places/fort-dobbs', null, 'America/New_York', now()),
  ('Grave of John King — Killed by an Elephant', 'grave-of-john-king-killed-by-an-elephant', 'weird-history', 35.23444, -80.84731, 'Charlotte', 'NC', 'John King was killed after being crushed by an escaped circus elephant in Charlotte. His gravestone carries a carved elephant, turning an already bizarre death into one of the city’s strangest cemetery markers.', 'open', 'https://www.atlasobscura.com/places/john-king-grave-crushed-by-elephant', null, 'America/New_York', now()),
  ('Musical Parking Garage', 'musical-parking-garage', 'roadside-oddities', 35.22781, -80.83781, 'Charlotte', 'NC', 'Artist Christopher Janney turned a nine-story parking garage into an enormous playable instrument. Touch-sensitive architectural fins light up and produce sounds, while programmed performances and a hidden puzzle add to the building’s interactive weirdness.', 'open', 'https://www.atlasobscura.com/places/musical-parking-garage', null, 'America/New_York', now()),
  ('Grove Park Inn — Secret Supreme Court Cold War Site', 'grove-park-inn-secret-supreme-court-cold-war-site', 'weird-history', 35.62018, -82.54287, 'Asheville', 'NC', 'During the Cold War, contingency plans designated Asheville’s Grove Park Inn as a relocation site where the U.S. Supreme Court could continue operating after a nuclear attack on Washington. The hotel is open to guests and visitors, but the former emergency shelter facilities themselves are not public.', 'limited', 'https://www.atlasobscura.com/places/grove-park-inn', null, 'America/New_York', now()),
  ('The Odd', 'the-odd', 'roadside-oddities', 35.58191, -82.60404, 'Asheville', 'NC', 'Taxidermy, animal skulls, jarred creatures, dolls’ heads, unusual memorabilia, and a 17th-century bezoar are integrated directly into the decor of this Asheville bar and performance space. It feels closer to an oddities cabinet crossed with a music venue than a normal neighborhood bar.', 'open', 'https://www.atlasobscura.com/places/odditorium', null, 'America/New_York', now()),
  ('The Lost Town of Proctor', 'the-lost-town-of-proctor', 'weird-history', 35.4733, -83.7264, 'Bryson City', 'NC', 'The remains of Proctor sit in one of the more isolated sections of Great Smoky Mountains National Park. Once a logging and settlement community, the town declined after the creation of the park and the construction of Fontana Dam; scattered foundations and remnants now require a substantial backcountry journey to reach.', 'limited', 'https://www.atlasobscura.com/things-to-do/north-carolina/history', null, 'America/New_York', now()),
  ('The Mother Vine', 'the-mother-vine', 'roadside-oddities', 35.925, -75.6684, 'Manteo', 'NC', 'A massive scuppernong grapevine on Roanoke Island may be centuries old and is often described as one of North America’s oldest cultivated grapevines. Historical documentation securely traces the vine back at least to the colonial era; it grows on private residential property whose owners have historically accommodated respectful visitors.', 'private', 'https://northcarolinahistory.org/encyclopedia/mother-vine/', null, 'America/New_York', now()),
  ('Blue Ghost Fireflies', 'blue-ghost-fireflies', 'roadside-oddities', 35.19702, -82.59431, 'Hendersonville', 'NC', 'For only a short period each year, rare blue ghost fireflies produce a sustained blue-green glow low over the forest floor rather than the familiar flashing pattern of common fireflies. The phenomenon is most associated with parts of western North Carolina and is best viewed through legitimate scheduled viewing opportunities when available. Tour information: https://www.visitnc.com/list/10-dark-sky-adventures-north-carolina', 'limited', 'https://www.atlasobscura.com/places/blue-ghost-fireflies', null, 'America/New_York', now()),
  ('Shipwreck Park — Mary E. Morris', 'shipwreck-park-mary-e-morris', 'weird-history', 33.90945, -78.08295, 'Oak Island', 'NC', 'The skeletal remains of the 138-foot cargo ship Mary E. Morris sit in a landscaped median in an Oak Island neighborhood. The vessel sank in 1893, spent roughly a century underwater, and was eventually moved onto land, creating the surreal sight of a shipwreck sitting in the middle of a street.', 'open', 'https://www.atlasobscura.com/places/shipwreck-park', null, 'America/New_York', now()),
  ('Fairy Ring', 'fairy-ring', 'roadside-oddities', 35.2102, -80.86024, 'Charlotte', 'NC', 'More than one hundred glowing fiberglass mushrooms form a permanent artificial fairy ring in Charlotte’s South End. Each mushroom contains internal lighting, creating a small illuminated fantasy landscape after dark.', 'open', 'https://www.atlasobscura.com/places/fairy-ring-light', null, 'America/New_York', now()),
  ('Monument to a Century of Flight', 'monument-to-a-century-of-flight', 'roadside-oddities', 36.09667, -75.71569, 'Kitty Hawk', 'NC', 'Hidden surprisingly well among trees near the Outer Banks visitor center, fourteen stainless-steel wing-shaped pylons commemorate one hundred major moments in aviation. The installation also contains a bronze globe, the poem “High Flight,” and a time capsule intended to remain sealed until 2103.', 'open', 'https://www.atlasobscura.com/places/monument-to-a-century-of-flight', null, 'America/New_York', now()),
  ('Corolla Wild Horses', 'corolla-wild-horses', 'roadside-oddities', 36.37891, -75.83219, 'Corolla', 'NC', 'A herd of Colonial Spanish mustangs lives along the remote northern Outer Banks, descendants of horses brought to the region centuries ago. They roam freely in the beach and dune environment north of Corolla; guided tours are the safest and most practical way for travelers to see them without disturbing the herd.', 'limited', 'https://www.atlasobscura.com/places/corolla-wild-horses', null, 'America/New_York', now()),
  ('Tory’s Den Cave', 'torys-den-cave', 'weird-history', 36.4019, -80.2995, 'Westfield', 'NC', 'A short trail in Hanging Rock State Park leads to a cool natural cave about twenty feet deep that is linked with Revolutionary War-era Tory history. The same access also reaches Tory’s Falls; this coordinate intentionally pins the official Tory’s Den parking area rather than an unreliable point in the woods. Access: https://www.ncparks.gov/park-features/hanging-rock-state-park-torys-den-parking-area', 'limited', 'https://www.ncparks.gov/state-parks/hanging-rock-state-park/trails', null, 'America/New_York', now()),
  ('Scoops Sculpture Garden', 'scoops-sculpture-garden', 'roadside-oddities', 36.48166, -80.76025, 'Mount Airy', 'NC', 'Behind a seasonal ice-cream stand, a wooded path leads through a surprisingly elaborate sculpture garden. The collection includes handmade figures, a forest chapel, religious-themed artwork, and a treehouse where visitors leave written messages; the sculpture garden itself is open beyond the ice-cream season.', 'open', 'https://www.atlasobscura.com/places/scoops-ice-cream-and-sculpture-garden', null, 'America/New_York', now()),
  ('Asheville Radio Museum', 'asheville-radio-museum', 'museums', 35.57114, -82.55586, 'Asheville', 'NC', 'A volunteer-run museum on the A-B Tech campus preserves more than a century of radio history through antique receivers, transmitters, vacuum tubes, early televisions, amateur-radio equipment, and working demonstrations. Its limited weekly hours make it a check-before-you-go stop.', 'limited', 'https://www.radiomuseum.org/museum/usa/southern-appalachian-radio-museum-asheville-nc/', null, 'America/New_York', now()),
  ('Grave of Spaghetti — The Carny Mummy', 'grave-of-spaghetti-the-carny-mummy', 'weird-history', 34.7846, -79.46227, 'Laurinburg', 'NC', 'Cancetto “Spaghetti” Farmica was a carnival worker whose unclaimed body reportedly spent years preserved at a Laurinburg funeral home before finally being buried in 1972. Local accounts say his grave was sealed beneath an extraordinary amount of concrete, giving the obscure showman one of North Carolina’s strangest burial stories.', 'open', 'https://www.roadsideamerica.com/tip/7849', null, 'America/New_York', now()),
  ('Soul City — Unrealized Utopia', 'soul-city-unrealized-utopia', 'weird-history', 36.40848, -78.27027, 'Manson', 'NC', 'Civil-rights leader Floyd McKissick envisioned Soul City as a new, racially integrated community with jobs, housing, industry, and political power built from the ground up. Federal support ended before the ambitious plan was realized, leaving a scattered landscape of surviving buildings and infrastructure from one of America’s most unusual planned-community experiments.', 'open', 'https://www.atlasobscura.com/places/soul-city', null, 'America/New_York', now()),
  ('Emerald Hollow Mine', 'emerald-hollow-mine', 'museums', 35.91373, -81.0829, 'Hiddenite', 'NC', 'This working mineral site allows visitors to prospect for emeralds, hiddenite, quartz, sapphires, garnets, and other stones by sluicing, creeking, or digging. The mine promotes itself as the only emerald mine in the United States open to public prospecting. Location reference: https://rockhoundr.com/emerald-hollow-mine-hiddenite-north-carolina/', 'limited', 'https://www.emeraldhollowmine.com/', null, 'America/New_York', now()),
  ('Arsenal Park — U.S. Arsenal Ghost Tower', 'arsenal-park-us-arsenal-ghost-tower', 'weird-history', 35.05393, -78.89455, 'Fayetteville', 'NC', 'Union troops destroyed the Fayetteville Arsenal in 1865, leaving foundations and scattered remains on the hillside. A modern steel framework outlines the shape of one of the vanished corner towers like an architectural ghost, making the missing structure visible without reconstructing it. Site information: https://museumofthecapefear.ncdcr.gov/', 'open', 'https://www.roadsideamerica.com/location/nc/all', null, 'America/New_York', now()),
  ('Evans Family Cemetery — Graves in a Mall Parking Lot', 'evans-family-cemetery-graves-in-a-mall-parking-lot', 'weird-history', 35.58635, -77.36881, 'Greenville', 'NC', 'A small fenced family cemetery containing 19th-century graves sits marooned inside the pavement surrounding Greenville Mall. Modern commercial development grew around the burial ground instead of removing it, leaving old headstones surrounded by parking spaces and traffic.', 'open', 'https://fotospot.com/attractions/north-carolina/cemetery-in-mall-parking-lot', null, 'America/New_York', now()),
  ('World’s Largest 1911 Pistol', 'worlds-largest-1911-pistol', 'roadside-oddities', 36.3073, -79.27759, 'Mebane', 'NC', 'A huge wooden reproduction of an M1911 pistol stands at Distinguished Pistol Outdoor Shooting Range. Built at roughly twelve times normal scale, the sculpture measures more than eight feet long and turns a familiar handgun silhouette into an oversized roadside object.', 'open', 'https://www.strangecarolinas.com/2024/06/ncs-biggest-1911-pistol-mebane-nc.html', null, 'America/New_York', now()),
  ('The Witches’ Keyhole', 'the-witches-keyhole', 'folklore', 35.92733, -81.52582, 'Lenoir', 'NC', 'Local tradition says an unusual keyhole-shaped opening in George Powell’s old house was intended to give witches or “haints” a way to escape instead of tormenting the occupants. The house was demolished decades ago, but the keyhole feature was preserved in a roadside display at Trinity United Methodist Church.', 'roadside', 'https://www.strangecarolinas.com/2015/06/the-witches-keyhole-lenoir-nc.html', null, 'America/New_York', now()),
  ('Fayetteville Eiffel Tower', 'fayetteville-eiffel-tower', 'roadside-oddities', 35.03029, -78.93064, 'Fayetteville', 'NC', 'An approximately 80-foot Eiffel Tower replica rises above the Bordeaux Center, a shopping complex whose French name inspired the landmark. Built in 1971 at roughly one-twelfth the height of the Paris original, it is one of Fayetteville’s most conspicuous pieces of roadside architecture.', 'roadside', 'https://www.roadsideamerica.com/tip/8512', null, 'America/New_York', now()),
  ('Appalachian Pinball Museum', 'appalachian-pinball-museum', 'museums', 35.31868, -82.46033, 'Hendersonville', 'NC', 'Dozens of playable pinball machines and classic arcade games fill this downtown museum, with admission generally allowing unlimited play rather than charging by the game. The collection spans multiple eras of mechanical and electronic arcade history.', 'open', 'https://www.atlasobscura.com/places/appalachian-pinball-museum', null, 'America/New_York', now()),
  ('Love Valley — Town with No Cars, Only Horses', 'love-valley-town-with-no-cars-only-horses', 'roadside-oddities', 35.98944, -80.98833, 'Love Valley', 'NC', 'Love Valley was deliberately built to resemble an Old West town and still keeps motor vehicles off its central streets. Visitors park outside the core and enter an unusual community where horses remain a normal form of transportation and hitching rails line the wooden storefronts.', 'open', 'https://lovevalley.com/', null, 'America/New_York', now()),
  ('Caged Monument of Important Rocks', 'caged-monument-of-important-rocks', 'roadside-oddities', 35.53455, -83.17181, 'Maggie Valley', 'NC', 'A fenced stone monument near Black Camp Gap contains hundreds of rocks gathered from around the world and cemented together in 1938. Accounts of the collection identify pieces associated with famous locations and events, including an Egyptian pyramid, the Alamo, and other improbably far-flung sources.', 'limited', 'https://www.roadsideamerica.com/story/68670', null, 'America/New_York', now()),
  ('Maniac — Indian Death Tiki of Awesomeness', 'maniac-indian-death-tiki-of-awesomeness', 'roadside-oddities', 35.51401, -83.12958, 'Maggie Valley', 'NC', 'A roughly 16-foot carved skeletal warrior stands outside Soco Cycles with huge teeth, empty eye sockets, a feathered headdress, and an oversized club. The deliberately monstrous carving has become one of Maggie Valley’s most unmistakable roadside figures.', 'roadside', 'https://www.roadsideamerica.com/story/42403', null, 'America/New_York', now()),
  ('Bucko’s Giant Moose', 'buckos-giant-moose', 'roadside-oddities', 35.59943, -80.81159, 'Mooresville', 'NC', 'A roughly 15-foot fiberglass moose known as Bucko stands beside East Plaza Drive. The oversized animal is a surviving example of the kind of attention-grabbing commercial sculpture that once appeared far more frequently along American highways.', 'roadside', 'https://fotospot.com/attractions/north-carolina/buckos-moose-statue', null, 'America/New_York', now()),
  ('Bear Grass Giant Fanged Bear', 'bear-grass-giant-fanged-bear', 'roadside-oddities', 35.76812, -77.12726, 'Bear Grass', 'NC', 'A large concrete bear with conspicuous fangs stands at Bear Grass Charter School as an unusually aggressive version of the community mascot. Sculptor Henry C. Cowan created the figure decades ago, and it remains visible from legitimate public approaches; avoid entering school grounds unnecessarily during class hours.', 'roadside', 'https://www.roadsideamerica.com/tip/42712', null, 'America/New_York', now()),
  ('U.S. Army Airborne & Special Operations Museum', 'us-army-airborne-special-operations-museum', 'roadside-oddities', 35.05594, -78.88555, 'Fayetteville', 'NC', 'This large Army museum traces airborne and special-operations history through full-size aircraft, vehicles, weapons, parachuting displays, immersive scenes, and major artifacts. Exhibits include equipment ranging from World War II gliders to modern special-operations hardware. Official Army listing: https://history.army.mil/Army-Museum-Enterprise/Find-an-Army-Museum/Airborne-and-Special-Operations-Museum/', 'limited', 'https://www.asomf.org/', null, 'America/New_York', now()),
  ('Igloo Ice Cream & Sandwich Shop', 'igloo-ice-cream-sandwich-shop', 'roadside-oddities', 36.20627, -81.24501, 'Millers Creek', 'NC', 'This old-school roadside restaurant is built with a rounded white facade designed to resemble an igloo. The business is still serving hot dogs, burgers, sandwiches, and ice cream in 2026, making the architecture a living roadside attraction rather than a preserved shell. Current listing: https://www.restaurantji.com/nc/millers-creek/igloo-ice-cream-and-sandwich-shop-/ Location reference: https://mapcarta.com/N6984550225', 'open', 'https://www.roadsideamerica.com/location/nc/all', null, 'America/New_York', now()),
  ('Daniel Boone Pioneer Giant at Bill’s Truck Stop', 'daniel-boone-pioneer-giant-at-bills-truck-stop', 'roadside-oddities', 35.75604, -80.34575, 'Linwood', 'NC', 'A giant bearded pioneer figure stands in the parking lot of Bill’s Truck Stop, where the old fiberglass advertising statue has survived multiple decades and relocations. A 2026 traveler report confirms the giant and the old-school truck stop are both still operating as an easy I-85 detour. Coordinates: https://virtualglobetrotting.com/map/pioneer-giant/ Current status: https://www.thetriumphadventures.com/glmc-trip-3/', 'open', 'https://www.roadsideamerica.com/tip/9085', null, 'America/New_York', now()),
  ('Soco Tower — “Most Photographed View in the Smokies”', 'soco-tower-most-photographed-view-in-the-smokies', 'roadside-oddities', 35.51264, -83.13508, 'Maggie Valley', 'NC', 'A tall roadside observation tower behind Soco Crafts has long advertised itself as offering the “Most Photographed View in the Smokies.” For a small admission fee, visitors climb above the trees for a panoramic mountain view; the attraction remains listed by Haywood County tourism with seasonal operation.', 'limited', 'https://visithaywood.com/listings/soco-tower-craft-shop/', null, 'America/New_York', now()),
  ('Harrier Jump Jet Display', 'harrier-jump-jet-display', 'roadside-oddities', 34.88252, -76.90652, 'Havelock', 'NC', 'Havelock’s close relationship with Marine Corps aviation is represented by a static AV-8 Harrier display in town. In 2026 Fleet Readiness Center East also restored and moved a two-seat TAV-8B Harrier to the Havelock Tourist and Event Center, adding another retired jump jet to a public collection of Marine aircraft. 2026 update: https://www.linkedin.com/posts/fleet-readiness-center-east_frce-fleetreadinesscentereast-av8bharrier-activity-7496225697993175040-6J6o Coordinate reference: https://virtualglobetrotting.com/map/mcdonnell-douglas-av-8-harrier-ii/', 'open', 'https://www.roadsideamerica.com/tip/3325', null, 'America/New_York', now())
on conflict (slug) do update set
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  website       = excluded.website,
  verified_at   = excluded.verified_at;

select count(*) as north_carolina from public.stops where state = 'NC';
